## Implementation Overview

This task integrates Stripe subscription management into the VolleyStats application to enforce team creation limits based on user subscription tiers.

## Database Schema Changes

### 1. Create new `subscriptions` table
```sql
-- supabase/migrations/YYYYMMDD_add_subscriptions.sql
CREATE TYPE public.subscription_tier AS ENUM ('free', 'standard', 'pro');
CREATE TYPE public.subscription_status AS ENUM ('active', 'canceled', 'past_due', 'incomplete');

CREATE TABLE public.subscriptions (
  id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
  user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL UNIQUE,
  tier public.subscription_tier NOT NULL DEFAULT 'free',
  status public.subscription_status NOT NULL DEFAULT 'active',
  stripe_customer_id text UNIQUE,
  stripe_subscription_id text UNIQUE,
  stripe_price_id text,
  team_limit integer NOT NULL DEFAULT 1,
  current_period_start timestamp with time zone,
  current_period_end timestamp with time zone,
  cancel_at_period_end boolean DEFAULT false,
  created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
  updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Add RLS policies
ALTER TABLE public.subscriptions ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Users can view their own subscription"
  ON public.subscriptions FOR SELECT
  USING (auth.uid() = user_id);

-- Only service role can insert/update (via Stripe webhooks)
CREATE POLICY "Service role can manage subscriptions"
  ON public.subscriptions FOR ALL
  USING (auth.role() = 'service_role');

-- Create index for faster lookups
CREATE INDEX idx_subscriptions_user_id ON public.subscriptions(user_id);
CREATE INDEX idx_subscriptions_stripe_customer_id ON public.subscriptions(stripe_customer_id);
```

### 2. Add subscription reference to profiles
```sql
ALTER TABLE public.profiles
  ADD COLUMN subscription_id uuid REFERENCES public.subscriptions(id) ON DELETE SET NULL;

CREATE INDEX idx_profiles_subscription_id ON public.profiles(subscription_id);
```

### 3. Create function to check team creation limit
```sql
CREATE OR REPLACE FUNCTION check_team_creation_limit()
RETURNS TRIGGER AS $$
DECLARE
  user_subscription RECORD;
  current_team_count INTEGER;
BEGIN
  -- Get user's subscription info
  SELECT s.tier, s.team_limit, s.status
  INTO user_subscription
  FROM public.subscriptions s
  WHERE s.user_id = NEW.user_id;

  -- Default to free tier if no subscription exists
  IF NOT FOUND THEN
    user_subscription.team_limit := 1;
    user_subscription.status := 'active';
  END IF;

  -- Only enforce limits for active subscriptions
  IF user_subscription.status != 'active' THEN
    RAISE EXCEPTION 'Subscription is not active. Please update your payment method.';
  END IF;

  -- Count existing teams for this user
  SELECT COUNT(*)
  INTO current_team_count
  FROM public.teams
  WHERE user_id = NEW.user_id;

  -- Check if limit would be exceeded
  IF current_team_count >= user_subscription.team_limit THEN
    RAISE EXCEPTION 'Team creation limit reached. Upgrade your subscription to create more teams. Current limit: %', user_subscription.team_limit;
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Add trigger to teams table
CREATE TRIGGER enforce_team_creation_limit
  BEFORE INSERT ON public.teams
  FOR EACH ROW
  EXECUTE FUNCTION check_team_creation_limit();
```

