### 4. Server-side API routes

`app/api/stripe/checkout/route.ts`:
```typescript
import { NextRequest, NextResponse } from 'next/server';
import { stripe } from '@/lib/stripe/client';
import { createServerClient } from '@/lib/supabase/server';

export async function POST(request: NextRequest) {
  try {
    const { tier } = await request.json();
    const supabase = createServerClient();

    const { data: { user }, error } = await supabase.auth.getUser();
    if (error || !user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    // Get or create Stripe customer
    const { data: subscription } = await supabase
      .from('subscriptions')
      .select('stripe_customer_id')
      .eq('user_id', user.id)
      .single();

    let customerId = subscription?.stripe_customer_id;

    if (!customerId) {
      const customer = await stripe.customers.create({
        email: user.email,
        metadata: { supabase_user_id: user.id }
      });
      customerId = customer.id;
    }

    // Price IDs (create these in Stripe Dashboard first)
    const priceIds = {
      standard: process.env.STRIPE_STANDARD_PRICE_ID!,
      pro: process.env.STRIPE_PRO_PRICE_ID!
    };

    const session = await stripe.checkout.sessions.create({
      customer: customerId,
      line_items: [{ price: priceIds[tier as 'standard' | 'pro'], quantity: 1 }],
      mode: 'subscription',
      success_url: `${process.env.NEXT_PUBLIC_APP_URL}/settings?subscription=success`,
      cancel_url: `${process.env.NEXT_PUBLIC_APP_URL}/settings?subscription=canceled`,
      metadata: { supabase_user_id: user.id, tier }
    });

    return NextResponse.json({ sessionId: session.id, url: session.url });
  } catch (error) {
    console.error('Checkout error:', error);
    return NextResponse.json({ error: 'Failed to create checkout session' }, { status: 500 });
  }
}
```

`app/api/stripe/webhook/route.ts`:
```typescript
import { NextRequest, NextResponse } from 'next/server';
import { stripe } from '@/lib/stripe/client';
import { supabase } from '@/lib/supabase/client';
import Stripe from 'stripe';

const TEAM_LIMITS = { free: 1, standard: 3, pro: 10 };

export async function POST(request: NextRequest) {
  const body = await request.text();
  const sig = request.headers.get('stripe-signature')!;

  let event: Stripe.Event;

  try {
    event = stripe.webhooks.constructEvent(body, sig, process.env.STRIPE_WEBHOOK_SECRET!);
  } catch (err) {
    return NextResponse.json({ error: 'Webhook signature verification failed' }, { status: 400 });
  }

  // Handle the event
  switch (event.type) {
    case 'checkout.session.completed': {
      const session = event.data.object as Stripe.Checkout.Session;
      const userId = session.metadata?.supabase_user_id;
      const tier = session.metadata?.tier as 'standard' | 'pro';

      if (userId && tier) {
        await supabase.from('subscriptions').upsert({
          user_id: userId,
          tier,
          status: 'active',
          stripe_customer_id: session.customer as string,
          stripe_subscription_id: session.subscription as string,
          team_limit: TEAM_LIMITS[tier],
          current_period_start: new Date().toISOString(),
          current_period_end: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString()
        });
      }
      break;
    }

    case 'customer.subscription.updated': {
      const subscription = event.data.object as Stripe.Subscription;
      const customerId = subscription.customer as string;

      const { data: existingSub } = await supabase
        .from('subscriptions')
        .select('user_id')
        .eq('stripe_customer_id', customerId)
        .single();

      if (existingSub) {
        await supabase.from('subscriptions').update({
          status: subscription.status as any,
          current_period_start: new Date(subscription.current_period_start * 1000).toISOString(),
          current_period_end: new Date(subscription.current_period_end * 1000).toISOString(),
          cancel_at_period_end: subscription.cancel_at_period_end
        }).eq('user_id', existingSub.user_id);
      }
      break;
    }

    case 'customer.subscription.deleted': {
      const subscription = event.data.object as Stripe.Subscription;
      await supabase.from('subscriptions').update({
        status: 'canceled',
        tier: 'free',
        team_limit: 1
      }).eq('stripe_subscription_id', subscription.id);
      break;
    }
  }

  return NextResponse.json({ received: true });
}
```

### 5. Create subscription API layer
`lib/api/subscriptions/index.ts`:
```typescript
import { Subscription } from '@/lib/types';
import { SupabaseDataStore } from '../supabase';
import { SupabaseClient } from '@supabase/supabase-js';

export const createSubscriptionApi = (supabaseClient?: SupabaseClient) => {
  const dataStore = new SupabaseDataStore('subscriptions', supabaseClient);

  return {
    getSubscription: async (userId: string): Promise<Subscription | null> => {
      const { data, error } = await dataStore.client
        .from('subscriptions')
        .select('*')
        .eq('user_id', userId)
        .maybeSingle();

      if (error) throw error;
      return data as Subscription | null;
    },

    checkTeamLimit: async (userId: string): Promise<{ canCreate: boolean; current: number; limit: number }> => {
      const subscription = await this.getSubscription(userId);
      const limit = subscription?.team_limit || 1;

      const { count } = await dataStore.client
        .from('teams')
        .select('*', { count: 'exact', head: true })
        .eq('user_id', userId);

      return {
        canCreate: (count || 0) < limit,
        current: count || 0,
        limit
      };
    }
  };
};
```

## UI Components

### 1. Subscription upgrade modal
`components/settings/subscription-upgrade-dialog.tsx`:
```typescript
'use client';

import { useState } from 'react';
import { loadStripe } from '@stripe/stripe-js';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Check } from 'lucide-react';
import { SUBSCRIPTION_TIERS } from '@/lib/types';

const stripePromise = loadStripe(process.env.NEXT_PUBLIC_STRIPE_PUBLISHABLE_KEY!);

export function SubscriptionUpgradeDialog({ open, onOpenChange }: { open: boolean; onOpenChange: (open: boolean) => void }) {
  const [loading, setLoading] = useState<string | null>(null);

  const handleUpgrade = async (tier: 'standard' | 'pro') => {
    setLoading(tier);
    try {
      const response = await fetch('/api/stripe/checkout', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ tier })
      });

      const { url } = await response.json();
      window.location.href = url;
    } catch (error) {
      console.error('Checkout error:', error);
    } finally {
      setLoading(null);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-4xl">
        <DialogHeader>
          <DialogTitle>Upgrade Your Subscription</DialogTitle>
        </DialogHeader>
        <div className="grid grid-cols-3 gap-4">
          {Object.entries(SUBSCRIPTION_TIERS).map(([key, tier]) => (
            <div key={key} className="border rounded-lg p-6">
              <h3 className="text-xl font-bold">{tier.name}</h3>
              <p className="text-3xl font-bold mt-4">${tier.price}<span className="text-sm">/mo</span></p>
              <ul className="mt-4 space-y-2">
                <li className="flex items-center gap-2">
                  <Check className="w-4 h-4" />
                  <span>{tier.teamLimit} team{tier.teamLimit > 1 ? 's' : ''}</span>
                </li>
                <li className="flex items-center gap-2">
                  <Check className="w-4 h-4" />
                  <span>Unlimited matches</span>
                </li>
                <li className="flex items-center gap-2">
                  <Check className="w-4 h-4" />
                  <span>Offline support</span>
                </li>
              </ul>
              {key !== 'free' && (
                <Button
                  className="w-full mt-6"
                  onClick={() => handleUpgrade(key as 'standard' | 'pro')}
                  disabled={loading === key}
                >
                  {loading === key ? 'Loading...' : 'Upgrade'}
                </Button>
              )}
            </div>
          ))}
        </div>
      </DialogContent>
    </Dialog>
  );
}
```

